short_answer:
```cpp
#include <iostream>

int fibonacci(int n) {
    if (n <= 1)
        return n;
    else 
        return fibonacci(n-1) + fibonacci(n-2);
}

int main() {
    int n = 10; // Example: Find the 10th Fibonacci number
    std::cout << "Fibonacci(" << n << ") = " << fibonacci(n) << std::endl;
    return 0;
}
```

