```python
def find_common_elements(arr1, arr2):
    # Initialize an empty set for storing unique elements from both arrays
    common_set = set()

    # Iterate through each element in array 1
    for num in arr1:
        # Check if the number is also present in array 2
        if num in arr2:
            # Add the number to the set of common elements
            common_set.add(num)

    return list(common_set)

